package config

import (
	"strings"
)

func GetNamespace() string {
	return EnvDefault("SIGNADOT_BASELINE_NAMESPACE", "hotrod")
}

func ExpandNamespace(v string) string {
	return strings.ReplaceAll(v, "<NAMESPACE>", GetNamespace())
}
package config

import (
	"os"
)

func GetOtelExporterType() string {
	return EnvDefault("OTEL_EXPORTER_TYPE", "otlp") // otlp or stdout
// limitations under the License.

package cmd

import (
	"github.com/spf13/cobra"
	"go.uber.org/zap"

	"github.com/signadot/hotrod/pkg/log"
	"github.com/signadot/hotrod/services/driver"
)

// driverCmd represents the driver command
var driverCmd = &cobra.Command{
	Use:   "driver",
	Short: "Starts Driver service",
	Long:  `Starts Driver service.`,
	RunE: func(cmd *cobra.Command, args []string) error {
		zapLogger := logger.With(zap.String("service", "driver"))
		logger := log.NewFactory(zapLogger)
		processor := driver.NewProcessor(
			logger,
		)
		return logError(zapLogger, processor.Run())
	},
}

func init() {
	RootCmd.AddCommand(driverCmd)
}
