async (page) => {
  const errs = [];
  page.on('console', m => { if (m.type() === 'error') errs.push(m.text()); });
  const reqs = [];
  page.on('response', r => { if (/ride-history|dispatch/.test(r.url())) reqs.push(`${r.request().method()} ${new URL(r.url()).pathname} ${r.status()}`); });
  await page.getByRole('combobox').first().selectOption('1');
  await page.getByRole('combobox').nth(1).selectOption('123');
  await page.getByRole('button', { name: 'Request Ride' }).click();
  await page.waitForFunction(() => /Fare:|Estimated fare/.test(document.body.innerText), null, { timeout: 30000 }).catch(e => errs.push('wait: ' + e.message));
  await page.waitForTimeout(4000);
  return { reqs, errs, len: (await page.content()).length, text: (await page.innerText('body')).replace(/\n+/g, ' | ').slice(0, 1200) };
}

