async (page) => {
  const K = 'lp4mnx3x5b9wg';
  const errs = [];
  page.on('console', m => { if (m.type() === 'error' && !/removeLayer/.test(m.text())) errs.push(m.text()); });
  page.on('pageerror', e => { if (!/removeLayer/.test(e.message)) errs.push(e.message); });
  const reqs = [];
  page.on('response', r => { if (/ride-history|dispatch/.test(r.url())) reqs.push(`${r.request().method()} ${new URL(r.url()).pathname} ${r.status()}`); });
  await page.unrouteAll();
  await page.route('**/*', async route => {
    const h = route.request().headers();
    const bag = h['baggage'] ? `${h['baggage']}, sd-routing-key=${K}` : `sd-routing-key=${K}`;
    await route.continue({ headers: { ...h, baggage: bag, tracestate: `sd-routing-key=${K}` } });
  });
  await page.goto('http://frontend.ctbench-hotrod.svc:8080/');
  await page.waitForLoadState('networkidle');
  await page.getByRole('combobox').first().selectOption('567');
  await page.getByRole('combobox').nth(1).selectOption('731');
  await page.getByRole('button', { name: 'Request Ride' }).click();
  await page.waitForFunction(() => /Estimated fare/.test(document.body.innerText), null, { timeout: 30000 });
  await page.waitForTimeout(4000);
  const rows = await page.getByTestId('ride-history-row').allInnerTexts();
  const countdown = await page.getByText(/Estimated fare/).first().innerText();
  const fareCell = page.getByTestId('ride-history-row').first().locator('td').last();
  const box = await fareCell.boundingBox(); const card = await page.getByTestId('ride-history').boundingBox();
  await page.screenshot({ path: '.playwright-mcp/after.png', fullPage: true });
  return { reqs, errs, countdown, total: await page.getByTestId('ride-history-total').innerText(), firstRow: rows[0], fareVisibleInCard: box.x + box.width <= card.x + card.width };
}

