cat > services/driver/best_eta_test.go <<'EOF'
package driver

import (
	"testing"
	"time"
)

func TestComputeFare(t *testing.T) {
	tests := []struct {
		eta  time.Duration
		want float64
	}{
		{0, 3.50},
		{time.Minute, 3.50},
		{2*time.Minute + 20*time.Second, 3.50}, // exactly the minimum
		{3 * time.Minute, 4.50},
		{4*time.Minute + 38*time.Second, 6.95},
		{10 * time.Minute, 15.00},
	}
	for _, tt := range tests {
		if got := computeFare(tt.eta); got != tt.want {
			t.Errorf("computeFare(%s) = %v, want %v", tt.eta, got, tt.want)
		}
	}
}
EOF
