  const K = 'lp4mnx3x5b9wg';
  await page.unrouteAll();
  await page.route('**/*', async route => {
    const h = route.request().headers();
    const bag = h['baggage'] ? `${h['baggage']}, sd-routing-key=${K}` : `sd-routing-key=${K}`;
    await route.continue({ headers: { ...h, baggage: bag, tracestate: `sd-routing-key=${K}` } });
  });
  await page.goto('http://frontend.ctbench-hotrod.svc:8080/');
  await page.waitForLoadState();
  await page.getByRole('combobox').first().selectOption('1');
  await page.getByRole('combobox').nth(1).selectOption('123');
  await page.getByRole('button', { name: 'Request Ride' }).click();
  const t1 = await page.locator("//div[p[2][contains(text(), 'route')]]/p[4]").textContent({ timeout: 15000 });
  const t2 = await page.locator("//div[p[2][contains(text(), 'driver')]]/p[4]").last().textContent();
  await page.waitForFunction(() => /Fare:/.test(document.body.innerHTML), null, {timeout: 20000});
  const t3 = await page.locator("//div[p[2][contains(text(), 'driver')]]/p[4]").last().textContent();
  return { t1, t2, t3, test1: t1 === 'Resolving routes', test2: /.*T7\d{5}C.*/.test(t3) };
}

